<script>(function($){var file=null;$('.ai-eye input').on('change',function(){$('.ai-eye label').removeClass('active');$(this).closest('label').addClass('active');});$('#uploadArea').on('click',function(){$('#fundusInput').click();});$('#fundusInput').on('change',function(){file=this.files[0];if(!file)return;if(file.size>10485760){alert('JPEG, PNG up to 10MB');this.value='';file=null;return;}if(!/^image\/(jpeg|png)$/.test(file.type)){alert('Please select a JPEG or PNG image.');this.value='';file=null;return;}var reader=new FileReader();reader.onload=function(e){$('#fundusPreview').attr('src',e.target.result).show();$('#uploadArea').hide();$('#removeImage').show();$('#analyzeImage').prop('disabled',false);$('#analysisResult').hide();$('#emptyAnalysis').show();};reader.readAsDataURL(file);});$('#removeImage').on('click',function(){file=null;$('#fundusInput').val('');$('#fundusPreview,#removeImage,#analysisResult').hide();$('#uploadArea,#emptyAnalysis').show();$('#analyzeImage').prop('disabled',true);});$('#analyzeImage').on('click',function(){if(!file)return;var button=$(this);button.addClass('ai-loading').prop('disabled',true);setTimeout(function(){button.removeClass('ai-loading').prop('disabled',false);$('#emptyAnalysis').hide();$('#analysisResult').fadeIn();},3000);});})(jQuery);</script>
